(function(){
'use strict';
const D=Night14Data,G=Night14;
window.Night14View={
 switcher(view){return `<label>探索方式</label><div class="gender-options view-options"><button data-action="view" data-view="3d" class="${view==='3d'?'active':''}" aria-pressed="${view==='3d'}">第三人称探索</button><button data-action="view" data-view="2d" class="${view==='2d'?'active':''}" aria-pressed="${view==='2d'}">平面调查</button></div>`;},
 game(state,icon,esc){const room=D.rooms[state.room];return `<section class="walk-ui" aria-label="3D自由探索界面">
 <header class="walk-header"><div class="walk-brand"><b>XIV</b><div>第十四夜<small>THE FOURTEENTH NIGHT</small></div></div><div class="walk-location"><small>${esc(room.en)}</small><h1>${esc(room.name)}</h1><span id="walk-coordinate">${esc(room.deck)}甲板</span></div><div class="walk-clock"><small>循环 ${String(state.cycle).padStart(2,'0')}</small><strong>00:${String(state.minute).padStart(2,'0')}</strong><span>终点 00:14</span></div></header>
 <nav class="walk-tools" aria-label="3D探索工具"><button data-action="board" aria-label="打开证据板">${icon('clue')}<span>证据 <b>${state.known.length}</b></span><kbd>B</kbd></button><button data-action="ship-map" aria-label="打开游轮地图">${icon('route')}<span>舱室图</span><kbd>M</kbd></button><button data-action="notebook" aria-label="打开夜航档案">${icon('book')}<span>档案</span><kbd>N</kbd></button><button data-action="walk-wait" aria-label="等待事件时间">${icon('clock')}<span>等待</span></button><button data-action="walk-flash" aria-label="开关手电筒">${icon('power')}<span>手电筒</span><kbd>F</kbd></button><button data-action="audio-settings" aria-label="声音与音乐"><span>声音</span>♪</button><button data-action="walk-pause" aria-label="暂停探索">${icon('help')}<span>暂停</span><kbd>Esc</kbd></button></nav>
 <div class="walk-chapter"><span>WORLD 01 / 14</span><i></i><span>永不靠岸的游轮</span></div><div id="crosshair" class="crosshair" aria-hidden="true"></div><div class="walk-compass" id="walk-compass">北 N</div>
 <section class="walk-mission"><small>当前调查 / INVESTIGATION</small><p>${esc(G.goal(state))}</p><span>${state.deductions.length} / 3 项推论 · ${state.xp} EXP</span></section>
 <button class="walk-interact" id="walk-interact" data-action="walk-interact" disabled><kbd>E</kbd><span><strong id="walk-target">寻找一段被遗忘的记忆</strong><small id="walk-target-sub">靠近物品或人物，再按 E 调查</small></span></button>
 <div class="walk-controls-note"><span><kbd>W A S D</kbd> 移动</span><span>拖动画面 · 转动视角</span><span>穿过舱门推进 1 分钟</span></div>
 <div class="walk-touch" aria-label="辅助移动控制"><button data-action="walk-nudge" data-direction="turn-left" aria-label="向左转动视角">↶</button><button data-action="walk-nudge" data-direction="forward" aria-label="向前移动">↑</button><button data-action="walk-nudge" data-direction="turn-right" aria-label="向右转动视角">↷</button><button data-action="walk-nudge" data-direction="left" aria-label="向左移动">←</button><button data-action="walk-nudge" data-direction="back" aria-label="向后移动">↓</button><button data-action="walk-nudge" data-direction="right" aria-label="向右移动">→</button></div>
 <div class="walk-pause shown" id="walk-pause"><div class="walk-pause-card"><small>YONGYE / IMMERSIVE EXPLORATION</small><h2>这一夜，走近真相。</h2><p>WASD 行走 · 拖动环绕主角查看<br>走近金色标记，按 E 调查或开门<br>B 证据板 · M 地图 · F 手电筒 · Esc 暂停</p><p class="walk-pause-sub">行走与阅读不走时。通过舱门推进 1 分钟。<br>进度与已发现线索会自动保存。</p><button class="button wide" data-action="walk-play" ${window.Night14Walk?'':'disabled'}>${window.Night14Walk?'开始自由探索 →':'正在准备 3D 画面…'}</button><div class="walk-pause-links"><button data-action="walk-lock">启用鼠标随视角</button><button data-action="view" data-view="2d">切换平面调查</button><button data-action="home">返回标题</button></div><p class="walk-pause-sub">鼠标随视角需再次点击画面；不支持时可直接拖动。<br>移动端可用方向按钮，右侧拖动查看。声音可在工具栏单独调整。</p></div></div></section>`;},
 map(state,esc){return `<p>你现在位于 <span class="gold">${esc(D.rooms[state.room].name)}</span>。靠近实体舱门，按 E 前往；地图用于辨认位置。</p><div class="ship-map">${Object.entries(D.rooms).map(([id,r])=>`<div class="ship-map-room ${id===state.room?'here':''}"><small>${r.deck}甲板 · ${r.en}</small><h3>${esc(r.name)}${id===state.room?' · 所在':''}</h3><p>舱门通往：${r.exits.map(to=>esc(D.rooms[to].name)).join(' / ')}</p><span>${id===state.room?'你在这里':G.gate(state,id)?esc(G.gate(state,id)):state.visits.includes(id)?'已到访':'等待探索'}</span></div>`).join('')}</div><button class="button secondary" data-action="close">收起地图，继续行走 →</button>`;},
 help:'<p>WASD 或方向按钮行走，Shift 加快步伐。拖动画面转向，左右方向键也可转向。走近金色标记或实体舱门，面向它按 E 调查或开门。</p><p>B 打开证据板，M 查看地图，N 查看档案，F 开关手电筒。Esc 暂停。阅读对话与切换页面时会停止移动。</p><p>通过舱门推进1分钟；行走和阅读不走时。等待可跳到事件，00:14重置，线索保留。旧版调查进度可继续使用。</p><p class="modal-note">本版使用风格化原创场景与人物模型。七个舱室之间通过舱门过渡；其余13个世界尚未开发。</p><button class="button" data-action="close">继续探索 →</button>'
};
})();
